import "fmt"

// ParseOctal converts an octal number represented as a string into its
// decimal (int64) equivalent. Invalid input is treated as octal 0, and an
// error is returned describing the invalid character or digit encountered.
func ParseOctal(input string) (int64, error) {
	var result int64

	if len(input) == 0 {
		return 0, fmt.Errorf("invalid octal input: %q", input)
	}

	for _, r := range input {
		if r < '0' || r > '7' {
			return 0, fmt.Errorf("invalid octal digit %q in input %q", r, input)
		}
		digit := int64(r - '0')
		result = result*8 + digit
	}

	return result, nil
}
"}

